/// (float table, byte table, [under, over, bad]) of a colormap by name.
pub fn table(name: &str) -> Option<(&'static [u64; 1024], &'static [u8; 1024], &'static [[u64; 4]; 3])> {
    match name {
        "inferno" => Some((&INFERNO_FLOAT, &INFERNO_BYTES, &INFERNO_EXTREMES)),
        "viridis" => Some((&VIRIDIS_FLOAT, &VIRIDIS_BYTES, &VIRIDIS_EXTREMES)),
        "magma" => Some((&MAGMA_FLOAT, &MAGMA_BYTES, &MAGMA_EXTREMES)),
        "plasma" => Some((&PLASMA_FLOAT, &PLASMA_BYTES, &PLASMA_EXTREMES)),
        "gray" => Some((&GRAY_FLOAT, &GRAY_BYTES, &GRAY_EXTREMES)),
        "RdBu_r" => Some((&RDBU_R_FLOAT, &RDBU_R_BYTES, &RDBU_R_EXTREMES)),
        "Blues" => Some((&BLUES_FLOAT, &BLUES_BYTES, &BLUES_EXTREMES)),
        _ => None,
    }
}
